mapper.update:
UPDATE products SET name=#{name},brief=#{brief},description=#{description},
  image_url=#{imageUrl},thumbnail_url=#{thumbnailUrl},business_version=business_version+1
WHERE id=#{productId} AND merchant_id=#{merchantId} AND business_version=#{expectedVersion}

UPDATE products SET monitor_profile=#{profile},business_version=business_version+1
WHERE id=#{productId} AND merchant_id=#{merchantId} AND business_version=#{expectedVersion}
  AND listing_product_id IS NULL

UPDATE products SET monitor_profile=CAST(#{profile} AS jsonb),business_version=business_version+1
WHERE id=#{productId} AND merchant_id=#{merchantId} AND business_version=#{expectedVersion}
  AND listing_product_id IS NULL
